INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 2, '{"stem": "一张100元可以换（　）枚1元，也可以换（　）张50元。", "options": null}', '100，2', '100元=100×1元，100÷50=2张。', 'paper', '["paper"]', 0, 1, '["paper_png/yg2_sx/p013.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 2, '{"stem": "一张100元可以换（　）张50元，也可以换（　）张20元，还可以换（　）张10元。", "options": null}', '2，5，10', '100÷50=2张，100÷20=5张，100÷10=10张。', 'paper', '["paper"]', 0, 1, '["paper_png/yg2_sx/p013.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '单选', 2, '{"stem": "这些钱正好能买下面的（　）。", "options": ["2元5角", "8元5角", "5元"]}', 'B', '根据答案页，这些钱的总数为8元5角，正好能买8元5角的物品。', 'paper', '["paper"]', 0, 1, '["paper_png/yg2_sx/p014.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '单选', 2, '{"stem": "欢欢买一个玩具要付8元4角，下面付钱方式正确的是（　）。\n①付1张5元、3张1元、4枚1角\n②付1张5元、1张2元、4枚1角\n③付5张1元、4枚1角", "options": null}', '①', '①5元+3×1元+4×1角=5元+3元+4角=8元4角 ✓
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '应用', 2, '{"stem": "想一想，算一算。\n商品价格：羽毛球8元、笔记本25元、文具盒4元、画笔4元8角、足球32元。\n（1）买一个羽毛球和一本笔记本，应付多少元多少角？", "options": null}', '33元0角', '羽毛球8元+笔记本25元=33元=33元0角。', 'paper', '["paper"]', 0, 1, '["paper_png/yg2_sx/p015.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '应用', 2, '{"stem": "想一想，算一算。\n商品价格：羽毛球8元、笔记本25元、文具盒4元、画笔4元8角、足球32元。\n（2）足球比文具盒贵多少元？", "options": null}', '28元', '足球32元-文具盒4元=28元。', 'paper', '["paper"]', 0, 1, '["paper_png/yg2_sx/p015.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '应用', 2, '{"stem": "想一想，算一算。\n商品价格：羽毛球8元、笔记本25元、文具盒4元、画笔4元8角、足球32元。\n（3）芳芳有40元，正好可以买哪两件物品？", "options": null}', '羽毛球和足球', '羽毛球8元+足球32元=40元，正好用完。', 'paper', '["paper"]', 0, 1, '["paper_png/yg2_sx/p016.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '应用', 2, '{"stem": "文具商店。\n商品价格：橡皮1角、尺子8角、铅笔5角、笔记本1元2角、铅笔2角、文具盒6元5角、画笔1元、玩具19元8角。\n（1）买一块橡皮、一把尺子和一支铅笔需要多少元多少角？", "options": null}', '1元4角', '橡皮1角+尺子8角+铅笔5角=14角=1元4角。', 'paper', '["paper"]', 0, 1, '["paper_png/yg2_sx/p016.png"]');
